<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Security\Csrf;use App\Services\Auth;use App\Services\FinanceService;Auth::requirePermission('PAYMENT_VIEW_SHIPPER');$c=Auth::context()['companies'][0]??null;if(!$c){http_response_code(403);exit('Company required.');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST')try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid token.');FinanceService::submitPayment((int)$_POST['payment_id'],(string)$_POST['method'],trim((string)$_POST['reference']),(float)$_POST['amount'],(string)($_POST['notes']??''),(int)Auth::user()['id']);header('Location: ?updated=1');exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}$rows=FinanceService::shipper((int)$c['company_id']);$pageTitle='Payments';require BASE_PATH.'/app/Views/layout/header.php';?><h1>Payments</h1><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><?php foreach($rows as$r):?><div class="card" style="margin-bottom:18px"><h2><?=h($r['payment_ref'].' · '.$r['shipment_ref'])?></h2><p><?=h($r['currency'].' '.number_format((float)$r['requested_amount'],2).' · '.$r['payment_status'])?></p><p>Due: <?=h($r['due_at'])?> · Reference: <?=h($r['transaction_reference']?:'—')?></p><?php if(in_array($r['payment_status'],['requested','rejected'],true)):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="payment_id" value="<?=h($r['payment_id'])?>"><div class="form-grid"><div class="field"><label>Method</label><select name="method"><option value="bank_transfer">Bank transfer</option><option value="mobile_money">Mobile money</option><option value="cash">Cash</option><option value="other">Other</option></select></div><div class="field"><label>Transaction reference</label><input name="reference" required></div><div class="field"><label>Amount paid</label><input type="number" step="0.01" min="0.01" name="amount" value="<?=h($r['requested_amount'])?>" required></div><div class="field"><label>Notes</label><input name="notes"></div></div><button class="button">Submit payment record</button></form><?php endif;?></div><?php endforeach;?><?php if(!$rows):?><div class="card"><p>No payment requests.</p></div><?php endif;?><?php require BASE_PATH.'/app/Views/layout/footer.php';?>